  _globals['_SEARCHEDTOOL'].fields_by_name['connections']._serialized_options = b'\222A\324\0062\321\006Connections for this tool\'s provider that the supplied identifier has a connected account for (any status), each with its own readiness state and connected_account_id. Populated only when identifier is supplied in the request. An empty array (`[]`) means this identifier does not have any connection at all for this tool\'s provider \342\200\224 not an error, and not the same as a connection listed with needs_connection (which means a connected account row exists but is inactive). A connection the identifier has never touched is left out of the array rather than listed as needs_connection. More than one entry means the identifier has accounts on multiple connections for this provider (e.g. two Slack workspaces) \342\200\224 inspect each entry\'s own readiness_state before using its connected_account_id, rather than assuming a single answer for the whole tool.'
  _globals['_CONNECTIONREADINESS'].fields_by_name['connection_name']._loaded_options = None
