  _globals['_CONNECTIONREADINESS'].fields_by_name['connected_account_id']._loaded_options = None
  _globals['_CONNECTIONREADINESS'].fields_by_name['connected_account_id']._serialized_options = b'\222A\331\0032\314\003ID of the connected account for this connection and the supplied identifier. Always populated when this entry is present, regardless of readiness_state \342\200\224 check readiness_state before using it: only TOOL_READINESS_STATE_READY means it is safe to pass to ExecuteTool now. For TOOL_READINESS_STATE_NEEDS_REAUTH or TOOL_READINESS_STATE_NEEDS_CONNECTION, this id refers to an existing but currently unusable account; ExecuteTool will fail until it is reconnected.J\010\"ca_123\"'
  _globals['_CONNECTIONREADINESS'].fields_by_name['readiness_state']._loaded_options = None
  _globals['_CONNECTIONREADINESS'].fields_by_name['readiness_state']._serialized_options = b'\222A\354\0052\351\005Whether this specific connection is usable right now for the supplied identifier, based on its own connected account\'s status \342\200\224 independent of every other connection listed for this provider. TOOL_READINESS_STATE_READY means connected_account_id above is safe to pass to ExecuteTool now; TOOL_READINESS_STATE_NEEDS_REAUTH means the connected account\'s token expired; TOOL_READINESS_STATE_NEEDS_CONNECTION means a connected account exists for this connection but is not active (e.g. disconnected). Either non-ready state still returns connected_account_id above \342\200\224 it identifies the existing account, but it is not usable until reconnected. A connection the identifier has never connected at all does not appear in the connections list at all.'
